/// <summary>
/// Static access to Exoforge services matching the extension runtime syntax.
/// In Unity, uses the ambient ExoforgeSDK.Client; in standalone applications, assign ExoServices.Client.
/// </summary>
public static class ExoServices
{
    private static Func<ExoClient>? _clientLocator;
    private static ExoClient? _fallbackClient;

    /// <summary>The active ExoClient used by static service calls.</summary>
    public static ExoClient Client
    {
        get
        {
            if (_clientLocator != null) return _clientLocator();
            if (_fallbackClient != null) return _fallbackClient;

            var unitySdkType = Type.GetType("Exoforge.Client.Unity.ExoforgeSDK, Exoforge.SDK")
                ?? Type.GetType("Exoforge.Client.Unity.ExoforgeSDK, Exoforge.SDK.Runtime")
                ?? Type.GetType("Exoforge.Client.Unity.ExoforgeSDK");

            if (unitySdkType == null)
            {
                try
                {
